199→func runExplainCheckpoint(ctx context.Context, w, errW io.Writer, checkpointIDPrefix string, noPager, verbose, full, rawTranscript, generate, force, searchAll bool) error {
200→	repo, err := openRepository(ctx)
201→	if err != nil {
202→		return fmt.Errorf("not a git repository: %w", err)
203→	}
204→
205→	store := checkpoint.NewGitStore(repo)
206→
207→	// First, try to find in committed checkpoints by checkpoint ID prefix
208→	committed, err := store.ListCommitted(ctx)
209→	if err != nil {
210→		return fmt.Errorf("failed to list checkpoints: %w", err)
211→	}
212→
213→	// Collect all matching checkpoint IDs to detect ambiguity
214→	var matches []id.CheckpointID
215→	for _, info := range committed {
216→		if strings.HasPrefix(info.CheckpointID.String(), checkpointIDPrefix) {
217→			matches = append(matches, info.CheckpointID)
218→		}
219→	}
220→
221→	var fullCheckpointID id.CheckpointID
222→	switch len(matches) {
223→	case 0:
224→		// Not found in committed, try temporary checkpoints by git SHA
225→		if generate {
226→			return fmt.Errorf("cannot generate summary for temporary checkpoint %s (only committed checkpoints supported)", checkpointIDPrefix)
227→		}
228→		output, found := explainTemporaryCheckpoint(ctx, w, repo, store, checkpointIDPrefix, verbose, full, rawTranscript)
229→		if found {
230→			outputExplainContent(ctx, w, output, noPager)
231→			return nil
232→		}
233→		// If output is non-empty, it contains an error message (e.g., ambiguous prefix)
234→		if output != "" {
235→			return errors.New(output)
236→		}
237→		return fmt.Errorf("checkpoint not found: %s", checkpointIDPrefix)
238→	case 1:
239→		fullCheckpointID = matches[0]
240→	default:
241→		// Ambiguous prefix - show up to 5 examples
242→		examples := make([]string, 0, 5)
243→		for i := 0; i < len(matches) && i < 5; i++ {
244→			examples = append(examples, matches[i].String())
245→		}
246→		return fmt.Errorf("ambiguous checkpoint prefix %q matches %d checkpoints: %s", checkpointIDPrefix, len(matches), strings.Join(examples, ", "))
247→	}
248→
249→	// Load checkpoint summary
250→	summary, err := store.ReadCommitted(ctx, fullCheckpointID)
251→	if err != nil {
252→		return fmt.Errorf("failed to read checkpoint: %w", err)
253→	}
254→	if summary == nil {
255→		return fmt.Errorf("checkpoint not found: %s", fullCheckpointID)
256→	}
257→
258→	// Load latest session content (needed for transcript and metadata)
259→	content, err := store.ReadLatestSessionContent(ctx, fullCheckpointID)
260→	if err != nil {
261→		return fmt.Errorf("failed to read checkpoint content: %w", err)
262→	}
263→
264→	// Handle summary generation
265→	if generate {
266→		if err := generateCheckpointSummary(ctx, w, errW, store, fullCheckpointID, summary, content, force); err != nil {
267→			return err
268→		}
269→		// Reload the content to get the updated summary
270→		content, err = store.ReadLatestSessionContent(ctx, fullCheckpointID)
271→		if err != nil {
272→			return fmt.Errorf("failed to reload checkpoint: %w", err)
273→		}
274→	}
275→
276→	// Handle raw transcript output
277→	if rawTranscript {
278→		if len(content.Transcript) == 0 {
279→			return fmt.Errorf("checkpoint %s has no transcript", fullCheckpointID)
280→		}
281→		// Output raw transcript directly (no pager, no formatting)
282→		if _, err = w.Write(content.Transcript); err != nil {
283→			return fmt.Errorf("failed to write transcript: %w", err)
284→		}
285→		return nil
286→	}
287→
288→	// Look up the author for this checkpoint (best-effort, ignore errors)
289→	author, _ := store.GetCheckpointAuthor(ctx, fullCheckpointID) //nolint:errcheck // Author is optional
290→
291→	// Find associated commits (git commits with matching Entire-Checkpoint trailer)
292→	associatedCommits, _ := getAssociatedCommits(ctx, repo, fullCheckpointID, searchAll) //nolint:errcheck // Best-effort
293→
